<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>SEO Proof Sort Board</title>
  <style>
    :root {
      --bg: #f6f1e8;
